    label: 'SLACK_TOKEN',
    kind: 'secret',
    pattern: /\bxox[abprs]-[0-9]{8,14}-[A-Za-z0-9-]{10,250}(?![\w-])/g,
    verify: notFiller,
    source: GITLEAKS,
  },
  {
